INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8134, 'អង្កត់ផ្ចិតគ្រាប់ខ្សាច់មួយស្មើ \(0.000\,021\) ម៉ែត្រ។ សរសេរជាទម្រង់ស្តង់ដា៖', NULL, '["\\(2.1 \\times 10^{5}\\) ម៉ែត្រ", "\\(2.1 \\times 10^{-5}\\) ម៉ែត្រ", "\\(21 \\times 10^{-6}\\) ម៉ែត្រ", "\\(2.1 \\times 10^{-4}\\) ម៉ែត្រ"]', 1, NULL, 3, 'mcq', 'ចល័តក្បៀសទៅស្តាំ \(5\) ខ្ទង់។', 'ស្វ័យគុណ', 'pisa', 1, '8', 'ស្វ័យគុណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8135, 'បាក់តេរីមួយប្រភេទបែងចែកជាពីរគ្រប់ម៉ោង។ ចាប់ផ្តើមមាន \(1\) ក្រោយ \(10\) ម៉ោងមានបាក់តេរីប៉ុន្មាន?', NULL, '["\\(1\\,024\\)", "\\(512\\)", "\\(20\\)", "\\(100\\)"]', 0, NULL, 3, 'mcq', '\(2^{10} = 1\,024\)។', 'ស្វ័យគុណ', 'pisa', 1, '8', 'ស្វ័យគុណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8136, 'សន្លឹកក្រដាសមួយបត់ជាពីរម្តងហើយម្តងទៀត។ បត់ \(6\) ដង ក្រដាសមានចំនួនស្រទាប់ប៉ុន្មាន?', NULL, '["\\(32\\)", "\\(12\\)", "\\(36\\)", "\\(64\\)"]', 3, NULL, 3, 'mcq', '\(2^6 = 64\)។', 'ស្វ័យគុណ', 'pisa', 1, '8', 'ស្វ័យគុណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8137, 'ក. សរសេរ \(6 \times 6 \times 6 \times 6 \times 6 \times 6 \times 6\) ជាស្វ័យគុណ រួចប្រាប់គោលនិងនិទស្សន្ត។ ខ. គណនា \(3^4\) និង \((-2)^7\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(6^7\) គោល \(6\) និទស្សន្ត \(7\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8138, 'សម្រួល ក. \((4^5)(4^2)(4^4)\) ខ. \(2 \times 2^3 \times 2^4 \times 2^7\) គ. \(\left(\dfrac{4}{3}\right)^4\left(\dfrac{4}{3}\right)^{-6}\left(\dfrac{4}{3}\right)^3\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(4^{5+2+4} = 4^{11}\) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8139, 'គណនា ក. \((4^3)(-3^2)\) ខ. \(\dfrac{4^3 - 2^2}{3(2^2)}\) គ. \(5^3 - 2^4 - 3^3\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \((64)(-9) = -576\) (2 ពិន្ទុ)
