INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8141, 'គណនា ក. \((2.5 \times 10^7)(3 \times 10^5)\) ខ. \(\dfrac{4.5 \times 10^7}{3 \times 10^5}\) ទុកលទ្ធផលជាទម្រង់ស្តង់ដា។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \((2.5 \times 3) \times 10^{7+5}\) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8142, 'គណនាតម្លៃនៃ \(3x^2y - 2xy^2\) ចំពោះ \(x = -5\) និង \(y = 4\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ជំនួសតម្លៃ \(3(-5)^2(4) - 2(-5)(4)^2\) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8143, 'សម្រួល \(\dfrac{(32a^2x^8)(-5a^4x^3)}{(5ax)(-2a^2x^2)(-4a^3x)}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ភាគយក \(32 \times (-5) = -160\) ; \(a^{2+4}x^{8+3} = a^6x^{11}\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8144, 'គណនា \((5m^2n^2 - 6)(m^3 - n^3)\) ចំពោះ \(m = -1\) និង \(n = 2\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ជំនួស \(5(-1)^2(2)^2 - 6 = 5(1)(4) - 6 = 14\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8145, 'សម្រួល \(\dfrac{\left(\dfrac{3}{2}a^2b^3\right)(2a^{-3}b^4)}{6a^{-2}b^4}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ភាគយក \(\left(\dfrac{3}{2} \times 2\right)a^{2-3}b^{3+4} = 3a^{-1}b^7\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8146, 'ចតុកោណកែងមួយមានបណ្តោយ \(b^3+1\) និងទទឹង \(b^2-1\)។ គណនាបរិមាត្រ បើ \(b = 3\)។', NULL, '[]', 0, NULL, 5, 'writing', 'បណ្តោយ \(3^3 + 1 = 28\) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8147, 'បាក់តេរីមួយប្រភេទបែងចែកជាពីរគ្រប់ម៉ោង ចាប់ផ្តើមពី \(1\) ។ ក. សរសេរចំនួនបាក់តេរីក្រោយ \(n\) ម៉ោងជាស្វ័យគុណ។ ខ. រកចំនួនក្រោយ \(10\) ម៉ោង។ គ. ក្រោយ \(12\) ម៉ោងច្រើនជាងក្រោយ \(10\) ម៉ោងប៉ុន្មានដង?', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(2^n\) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8148, 'ចម្ងាយពីផែនដីទៅព្រះអាទិត្យប្រហែល \(9.3 \times 10^7\) ម៉ាយល៍។ ក. សរសេរជាចំនួនធម្មតា។ ខ. បើយានមួយធ្វើដំណើរ \(3 \times 10^3\) ម៉ាយល៍ក្នុងមួយម៉ោង តើប្រើពេលប៉ុន្មានម៉ោង? ទុកជាទម្រង់ស្តង់ដា។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(9.3 \times 10^7 = 93\,000\,000\) ម៉ាយល៍ (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8149, 'ការ៉េមួយមានផ្ទៃក្រឡា \(\mathcal{A} = 144\ \text{cm}^2\)។ ក. រកប្រវែងជ្រុង។ ខ. រកបរិមាត្រ។ គ. គូបមួយមានជ្រុងដូចគ្នានឹងការ៉េនេះ រកមាឌរបស់គូប។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(a = \sqrt{144} = 12\ \text{cm}\) (2 ពិន្ទុ)
